/// <summary>
/// Custom Helper class for SharePoint related methods
/// </summary>
using Microsoft.Dynamics365.LocalizationFramework;
using Microsoft.Dynamics.AX.Framework.FileManagement;
using Microsoft.Dynamics.Platform.Integration.SharePoint;
public class METSharePointHelper
{
}

Method.Source:
    /// <summary>
    /// Upload a file data in System.IO.MemoryStream format to Sharepoint location specified using DocumentTypeId
    /// </summary>
    /// <param name = "memoryStream">file data</param>
    /// <param name = "filename">filename</param>
    /// <param name = "_docuTypeId">Docu Type Id for SharePoint Location</param>
    /// <returns>true if successfully uploads the file to SharePoint, else false</returns>
    public static boolean saveToSharepoint(System.IO.MemoryStream memoryStream, Filename filename, DocuTypeId _docuTypeId)
    {
        boolean ret;

        try
        {
            //save to SharePoint location
            DocuType docuType = DocuType::find(_docuTypeId);//ERBDDocuUtils::sharepointDocuType();
            
            if(!docuType || docuType.FilePlace != DocuFilePlace::SharePoint)
            {
                throw error(strFmt("@MET:SharePointPathErrorMessage",_docuTypeId));
            }

            Microsoft.Dynamics.AX.Framework.FileManagement.SharePointDocumentStorageProvider provider;
            provider = Docu::GetStorageProvider(docuType, true, curUserId());

            //System.IO.MemoryStream memoryStream = new System.IO.MemoryStream(reportBytes);
            provider.SaveFileWithOverwrite(newGuid(), filename, System.Web.MimeMapping::GetMimeMapping(filename), memoryStream);

            Info(strFmt("@MET:SharepointFileUploadSuccessMessage", docuType.FolderPath));

            ret = true;
        }
        catch (Exception::CLRError)
        {
            warning(CLRInterop::getLastException().toString());
        }
        catch
        {
            warning("@MET:SharePointUnhandledError");
        }

        return ret;
    }

    /// <summary>
    /// Save file to SharePoint and verify upload
    /// </summary>
    /// <param name = "memoryStream">filestream</param>
    /// <param name = "filename">filename</param>
    /// <param name = "_docuTypeId">docutype</param>
    /// <returns>boolean</returns>
    public static boolean saveToSharepointSync(System.IO.MemoryStream memoryStream, Filename filename, DocuTypeId _docuTypeId)
    {
        boolean ret;

        try
        {
            //save to SharePoint location
            DocuType docuType = DocuType::find(_docuTypeId);
            
            if(!docuType || docuType.FilePlace != DocuFilePlace::SharePoint)
            {
                throw error(strFmt("@MET:SharePointPathErrorMessage",_docuTypeId));
            }

            Microsoft.Dynamics.AX.Framework.FileManagement.SharePointDocumentStorageProvider provider;

            provider = Docu::GetStorageProvider(docuType, true, curUserId());

            //System.IO.MemoryStream memoryStream = new System.IO.MemoryStream(reportBytes);
            provider.SaveFileWithOverwrite(newGuid(), filename, System.Web.MimeMapping::GetMimeMapping(filename), memoryStream);

            int retries = 0;
            boolean isUploaded = METSharePointHelper::IsUploadSuccessful(docuType, filename);
            if (!isUploaded  && retries < 20)
            {
                sleep(1000); 
                isUploaded = METSharePointHelper::IsUploadSuccessful(docuType, filename);
                retries++;
            }

            Info(strFmt("@MET:SharepointFileUploadSuccessMessage", docuType.FolderPath));

            ret = true;
        }
        catch (Exception::CLRError)
        {
            warning(CLRInterop::getLastException().toString());
        }
        catch
        {
            warning("@MET:SharePointUnhandledError");
        }

        return ret;
    }

    /// <summary>
    /// This method checks whether the file is successfully uploaded to SharePoint location
    /// </summary>
    /// <param name = "_docuType">DocuType</param>
    /// <param name = "_fileName">filename</param>
    /// <returns>true</returns>
    public static boolean IsUploadSuccessful(DocuType  _docuType, Filename _fileName)
    {
        boolean ret = false;
        ISharePointProxy proxy = SharePointHelper::createProxyWithAuthenticator(_docuType.Host, _docuType.Site, OfficeSharePoint::GetAuthenticator(_docuType.Host));
        FileResults fileResults = SharePointHelper::GetFiles(proxy, _docuType.FolderPath, _fileName);

        if (fileResults && fileResults.Results)
        {
            ret = true;
        }

        return ret;

    }
